use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,path::Path,collections::BTreeMap,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-groups-sdk175";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let root=Path::new(R);assert!(!root.join("runs").exists());let ids:Value=serde_json::from_slice(&fs::read(root.join("identities.json")).unwrap()).unwrap();let mut pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(root.join("pins.json")).unwrap()).unwrap();let mut rows=vec![];
for v in["accepted","OFF","ON"]{let binary=ids[v]["binary"].as_str().unwrap();let nm=Command::new("nm").args(["-S","--size-sort","--defined-only",binary]).output().unwrap();assert!(nm.status.success());let text=String::from_utf8(nm.stdout).unwrap();let count=text.lines().filter(|l|l.contains("grouping9index_map")).count();if v=="ON"{assert!(count>=2);}else{assert_eq!(count,0);}
let mut found=0;for line in text.lines().filter(|l|l.contains("grouping13scalar_groups")){let sym=line.split_whitespace().last().unwrap();let out=Command::new("objdump").args(["-d","--no-show-raw-insn"]).arg(format!("--disassemble={sym}")).arg(binary).output().unwrap();assert!(out.status.success());let path=root.join(format!("codegen/{v}-grouping-{found}.asm"));fs::write(&path,out.stdout).unwrap();pins.insert(path.display().to_string(),hash(&path));rows.push(json!({"variant":v,"binary_sha256":hash(binary),"symbol":sym,"symbol_row":line,"new_dictionary_symbols":count,"disassembly":path,"disassembly_sha256":hash(&path)}));found+=1;}assert!(found>0);}
let file=root.join("map-code-audit.json");fs::write(&file,serde_json::to_vec_pretty(&json!({"linked_routing_checked":true,"not_dynamic_work_or_speed_claim":true,"rows":rows})).unwrap()).unwrap();for path in[file,root.join("audit.rs"),root.join("audit")]{pins.insert(path.display().to_string(),hash(&path));}fs::write(root.join("pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();println!("Linked new dictionary symbols only ON; real grouping disassembly pinned for all3; {}capture pins",pins.len());
}
